use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
{
    let mut out: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == a[j],
        decreases a.len() - i,
    {
        // push the next element; since T: Copy, reading a[i] copies the value
        out.push(a[i]);
        i = i + 1;
    }

    out
}

} // verus!

